'use client';

import React, { useState } from 'react';
import { TraceStep } from '../lib/types';
import { decideEscalation } from '../lib/backend';

interface TraceabilityProps {
  steps: TraceStep[];
  isRealMode: boolean;
  onDecisionMade?: (approvalId: string, decision: 'approved' | 'rejected', resultText: string) => void;
}

export const Traceability: React.FC<TraceabilityProps> = ({
  steps,
  isRealMode,
  onDecisionMade,
}) => {
  const [loadingApprovalId, setLoadingApprovalId] = useState<string | null>(null);

  const handleDecision = async (approvalId: string | undefined, decision: 'approved' | 'rejected') => {
    if (!approvalId) {
      alert('⚠️ No se puede ejecutar la decisión: la acción no trae un approvalId válido de aprobación.');
      return;
    }

    setLoadingApprovalId(approvalId);

    if (isRealMode) {
      const res = await decideEscalation(approvalId, decision);
      if (res.ok && res.data) {
        const statusText = decision === 'approved' ? 'Escalamiento Aprobado' : 'Escalamiento Rechazado';
        if (onDecisionMade) {
          onDecisionMade(approvalId, decision, `${statusText} (Caso #${res.data.case?.caseId})`);
        }
      } else {
        alert(`Error al registrar decisión: ${res.problem?.title || 'Fallo de petición'}`);
      }
    } else {
      // Simulated decision
      setTimeout(() => {
        const statusText = decision === 'approved' ? 'Escalamiento Aprobado' : 'Escalamiento Rechazado';
        if (onDecisionMade) {
          onDecisionMade(approvalId, decision, `${statusText} (Modo Simulado)`);
        }
      }, 400);
    }
    setLoadingApprovalId(null);
  };

  return (
    <div className="panel-card" style={{ flex: 1, minHeight: '300px' }}>
      <div className="panel-header">
        <span>Trazabilidad de Acciones</span>
        <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)', fontWeight: 500 }}>
          ({steps.length} pasos)
        </span>
      </div>

      <div className="trace-list" role="feed" aria-label="Lista de trazabilidad de acciones">
        {steps.length === 0 ? (
          <div className="empty-state">
            Sin acciones registradas para este hilo aún.
          </div>
        ) : (
          steps.map((step) => {
            const isPending = step.actorType === 'human_pending';
            const isApproved = step.actorType === 'human_approved';
            const isRejected = step.actorType === 'human_rejected';

            let ringClass = 'blue';
            if (isPending) ringClass = 'red';
            if (isApproved) ringClass = 'green';
            if (isRejected) ringClass = 'gray';

            let tagLabel = 'Bot/Agente AI';
            let tagClass = 'bot';

            if (isPending) {
              tagLabel = 'Humano (en espera)';
              tagClass = 'human-pending';
            } else if (isApproved) {
              tagLabel = 'Humano · Aprobado por Operador';
              tagClass = 'human-approved';
            } else if (isRejected) {
              tagLabel = 'Humano · Rechazado por Operador';
              tagClass = 'human-rejected';
            }

            return (
              <div key={step.id} className="trace-item">
                <div className={`trace-ring ${ringClass}`} />

                <div className="trace-content">
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span className={`trace-tag ${tagClass}`}>{tagLabel}</span>
                    <span style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>{step.timestamp}</span>
                  </div>

                  <div className="trace-title">{step.title}</div>

                  {isPending && (
                    <div style={{ marginTop: '0.4rem' }}>
                      {!step.approvalId ? (
                        <div style={{ color: 'var(--red-primary)', fontSize: '0.75rem', fontStyle: 'italic' }}>
                          ⚠ Acción invasiva sin approvalId. No se puede decidir.
                        </div>
                      ) : (
                        <div className="trace-actions">
                          <button
                            className="btn-decision-no"
                            onClick={() => handleDecision(step.approvalId, 'rejected')}
                            disabled={loadingApprovalId === step.approvalId}
                            type="button"
                          >
                            {loadingApprovalId === step.approvalId ? '...' : 'NO'}
                          </button>
                          <button
                            className="btn-decision-yes"
                            onClick={() => handleDecision(step.approvalId, 'approved')}
                            disabled={loadingApprovalId === step.approvalId}
                            type="button"
                          >
                            {loadingApprovalId === step.approvalId ? '...' : 'SÍ'}
                          </button>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};
