'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import Link from 'next/link';
import { ModeSwitch } from '../../components/ModeSwitch';
import { ConversationList } from '../../components/ConversationList';
import { Chat } from '../../components/Chat';
import { ClientProfile } from '../../components/ClientProfile';
import { Traceability } from '../../components/Traceability';
import {
  ConversationSnapshot,
  DemoActor,
  TraceStep,
  TransactionEvidence,
  DisputeCase,
  ConversationMessage,
} from '../../lib/types';
import {
  getDemoActors,
  createDemoSession,
  getCurrentSession,
  getConversations,
  getConversationThread,
  getTransactionEvidence,
  getDisputeCase,
} from '../../lib/backend';
import { useRealtime } from '../../lib/realtime';

export default function BackofficePage() {
  const [actors, setActors] = useState<DemoActor[]>([]);
  const [selectedActor, setSelectedActor] = useState('demo-backoffice-1');
  const [isConnecting, setIsConnecting] = useState(false);
  const [sessionRole, setSessionRole] = useState<string | null>(null);

  const [conversations, setConversations] = useState<ConversationSnapshot[]>([]);
  const [selectedThreadId, setSelectedThreadId] = useState<string | null>(null);
  const [traceStepsMap, setTraceStepsMap] = useState<Record<string, TraceStep[]>>({});

  const [realTxEvidence, setRealTxEvidence] = useState<TransactionEvidence | null>(null);
  const [realCase, setRealCase] = useState<DisputeCase | null>(null);

  const [isTyping, setIsTyping] = useState(false);
  const [systemAlert, setSystemAlert] = useState<string | null>(null);
  const [problemAlert, setProblemAlert] = useState<string | null>(null);

  const hasInitializedRef = useRef(false);

  const selectedConversation = conversations.find((c) => c.threadId === selectedThreadId) || (conversations.length > 0 ? conversations[0] : null);

  const buildTraceStepsForSnapshot = (snapshot: ConversationSnapshot): TraceStep[] => {
    const steps: TraceStep[] = [
      {
        id: `step-norm-${snapshot.threadId}`,
        title: '1. Identificación RAG & Normalización de Consulta',
        timestamp: new Date(snapshot.trace?.updatedAt || Date.now()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        isInvasive: false,
        actorType: 'bot',
        status: 'approved',
      },
      {
        id: `step-pol-${snapshot.threadId}`,
        title: '2. Evaluación de Políticas de Riesgo (DisputePolicyEngine)',
        timestamp: new Date(snapshot.trace?.updatedAt || Date.now()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        isInvasive: false,
        actorType: 'bot',
        status: 'approved',
      },
    ];

    const hasApproval = Boolean(
      snapshot.trace?.approvalId || snapshot.trace?.status === 'pending_approval'
    );

    if (hasApproval) {
      const isPending = snapshot.trace?.status === 'pending_approval';
      const isDenied = snapshot.trace?.status === 'denied';

      steps.unshift({
        id: `step-appr-${snapshot.threadId}-${snapshot.trace?.approvalId || 'demo'}`,
        title: '3. Escalamiento de Disputa (#demo-case-1) — Aprobación Requerida',
        timestamp: new Date(snapshot.trace?.updatedAt || Date.now()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        isInvasive: true,
        actorType: isPending ? 'human_pending' : isDenied ? 'human_rejected' : 'human_approved',
        approvalId: snapshot.trace?.approvalId || 'appr-demo-450',
        status: isPending ? 'pending' : isDenied ? 'rejected' : 'approved',
      });
    }

    return steps;
  };

  const fetchRealData = useCallback(async () => {
    const convsRes = await getConversations();
    if (convsRes.ok && convsRes.data) {
      setConversations(convsRes.data);

      // Build trace steps for all fetched snapshots
      const newTraceMap: Record<string, TraceStep[]> = {};
      for (const snap of convsRes.data) {
        newTraceMap[snap.threadId] = buildTraceStepsForSnapshot(snap);
      }
      setTraceStepsMap((prev) => ({ ...prev, ...newTraceMap }));

      if (convsRes.data.length > 0) {
        setSelectedThreadId((prev) => {
          if (!prev || !convsRes.data?.some((c) => c.threadId === prev)) {
            return convsRes.data![0].threadId;
          }
          return prev;
        });
      }
    }

    const txRes = await getTransactionEvidence('demo-transaction-1');
    if (txRes.ok && txRes.data) setRealTxEvidence(txRes.data);

    const caseRes = await getDisputeCase('demo-case-1');
    if (caseRes.ok && caseRes.data) setRealCase(caseRes.data);
  }, []);

  const onSnapshot = useCallback((snapshot: ConversationSnapshot) => {
    setConversations((prev) => {
      const idx = prev.findIndex((c) => c.threadId === snapshot.threadId);
      if (idx >= 0) {
        const next = [...prev];
        const existingMessages = prev[idx].messages || [];
        const mergedMessages = (snapshot.messages || []).map((sMsg, mIdx) => {
          if (sMsg.role === 'customer' && sMsg.content?.includes('[Mensaje de cliente recibido')) {
            const localMatch = existingMessages[mIdx] || existingMessages.find((m) => m.messageId === sMsg.messageId);
            if (localMatch && localMatch.content && !localMatch.content.includes('[Mensaje de cliente recibido')) {
              return { ...sMsg, content: localMatch.content };
            }
          }
          return sMsg;
        });
        next[idx] = { ...snapshot, messages: mergedMessages };
        return next;
      }
      return [snapshot, ...prev];
    });

    setTraceStepsMap((prevMap) => ({
      ...prevMap,
      [snapshot.threadId]: buildTraceStepsForSnapshot(snapshot),
    }));
  }, []);

  const onAlert = useCallback(({ approvalId, threadId }: { approvalId: string; threadId: string | null }) => {
    const targetThread = threadId || selectedThreadId || undefined;
    if (!targetThread) return;

    setTraceStepsMap((prevMap) => {
      const currentSteps = prevMap[targetThread] || [];
      if (!currentSteps.some((s) => s.approvalId === approvalId)) {
        const newStep: TraceStep = {
          id: `step-alert-${Date.now()}`,
          title: `3. Escalamiento de Disputa (#demo-case-1) — Aprobación Requerida`,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          isInvasive: true,
          actorType: 'human_pending',
          approvalId,
          status: 'pending',
        };
        return {
          ...prevMap,
          [targetThread]: [newStep, ...currentSteps],
        };
      }
      return prevMap;
    });
  }, [selectedThreadId]);

  const realtime = useRealtime({
    enabled: true,
    onSnapshot,
    onAlert,
    onStateChange: ({ status }) => {
      setIsTyping(status === 'generating' || status === 'deciding' || status === 'queued');
    },
    onCompleted: () => setIsTyping(false),
    onProblem: ({ code }) => setProblemAlert(`Error del servidor: ${code}`),
  });

  const handleConnect = useCallback(async (actorToUse = selectedActor) => {
    setIsConnecting(true);
    const res = await createDemoSession(actorToUse);
    if (res.ok) {
      const meRes = await getCurrentSession();
      if (meRes.ok && meRes.data) {
        setSessionRole(meRes.data.roles[0] || 'backoffice');
      }
      realtime.connect();
      await fetchRealData();
    }
    setIsConnecting(false);
  }, [selectedActor, realtime, fetchRealData]);

  useEffect(() => {
    if (hasInitializedRef.current) return;
    hasInitializedRef.current = true;

    getDemoActors().then((res) => {
      if (res.ok && res.data) setActors(res.data);
    });
    handleConnect('demo-backoffice-1');
  }, [handleConnect]);

  // Periodic silent auto-refresh for live customer threads after session is set
  useEffect(() => {
    if (!sessionRole) return;
    const timer = setInterval(() => {
      fetchRealData();
    }, 2000);
    return () => clearInterval(timer);
  }, [fetchRealData, sessionRole]);

  const handleSelectThread = async (threadId: string) => {
    setSelectedThreadId(threadId);
    if (threadId && !threadId.startsWith('sim-')) {
      realtime.subscribeThread(threadId);
      const res = await getConversationThread(threadId);
      if (res.ok && res.data) {
        onSnapshot(res.data);
      }
    }
  };

  const handleSendMessage = (text: string, attachmentIds: string[] = []) => {
    if (!selectedThreadId) return;

    const newMsg: ConversationMessage = {
      messageId: `bo-msg-${Date.now()}`,
      role: 'backoffice',
      content: text,
      attachments: [],
      createdAt: new Date().toISOString(),
    };

    setConversations((prev) =>
      prev.map((c) =>
        c.threadId === selectedThreadId
          ? { ...c, messages: [...c.messages, newMsg] }
          : c
      )
    );

    realtime.sendChat({
      clientMessageId: newMsg.messageId,
      text,
      threadId: selectedThreadId,
      attachmentIds,
    });
  };

  const handleDecisionMade = (approvalId: string, decision: 'approved' | 'rejected', resultText: string) => {
    if (!selectedThreadId) return;

    setTraceStepsMap((prevMap) => {
      const currentSteps = prevMap[selectedThreadId] || [];
      const updatedSteps = currentSteps.map((step) => {
        if (step.approvalId === approvalId) {
          return {
            ...step,
            actorType: decision === 'approved' ? ('human_approved' as const) : ('human_rejected' as const),
            status: decision === 'approved' ? ('approved' as const) : ('rejected' as const),
          };
        }
        return step;
      });
      return { ...prevMap, [selectedThreadId]: updatedSteps };
    });

    const decisionText = decision === 'approved'
      ? `✅ [DECISIÓN REGISTRADA]: El operador de Backoffice ha APROBADO la devolución por $450 USD. (${resultText})`
      : `❌ [DECISIÓN REGISTRADA]: El operador de Backoffice ha RECHAZADO la devolución por $450 USD. (${resultText})`;

    handleSendMessage(decisionText);
  };

  const currentSteps = (selectedThreadId && traceStepsMap[selectedThreadId]) || [];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', backgroundColor: 'var(--bg-color)' }}>
      <ModeSwitch
        actors={actors}
        selectedActor={selectedActor}
        onSelectActor={(id) => {
          setSelectedActor(id);
          handleConnect(id);
        }}
        onConnect={() => handleConnect()}
        isConnecting={isConnecting}
        isConnected={realtime.isConnected}
        sessionRole={sessionRole}
      />

      <div style={{ padding: '0.6rem 1.5rem', backgroundColor: 'var(--surface-color)', borderBottom: '1px solid var(--line-color)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-ink)' }}>
          🛡️ Ambiente 2 — Consola de Backoffice (Operador)
        </div>
        <Link href="/" className="btn-secondary" style={{ padding: '0.2rem 0.6rem', fontSize: '0.8rem' }}>
          ← Volver al Inicio
        </Link>
      </div>

      {/* 3-Column Wireframe Layout */}
      <main className="backoffice-container">
        {/* Column 1: Conversations List */}
        <ConversationList
          conversations={conversations}
          selectedThreadId={selectedThreadId}
          onSelectThread={handleSelectThread}
          onRefresh={fetchRealData}
        />

        {/* Column 2: Selected Thread Chat */}
        <div className="panel-card">
          <div className="panel-header">
            <span>
              Hilo Activo: {selectedConversation?.ownerUserId || 'Cliente'} {selectedThreadId ? `(#${selectedThreadId.slice(0, 12)})` : ''}
            </span>
          </div>

          <Chat
            messages={selectedConversation?.messages || []}
            onSendMessage={handleSendMessage}
            isTyping={isTyping}
            systemAlert={systemAlert}
            problemAlert={problemAlert}
            placeholder="Responder como operador de Backoffice..."
            isRealMode={true}
          />
        </div>

        {/* Column 3: Stacked Profile & Traceability */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem', height: '100%' }}>
          <ClientProfile
            isRealMode={true}
            realTxEvidence={realTxEvidence}
            realCase={realCase}
          />

          <Traceability
            steps={currentSteps}
            isRealMode={true}
            onDecisionMade={handleDecisionMade}
          />
        </div>
      </main>
    </div>
  );
}
