'use client';

import React, { useState } from 'react';
import { ConversationSnapshot } from '../lib/types';

interface ConversationListProps {
  conversations: ConversationSnapshot[];
  selectedThreadId: string | null;
  onSelectThread: (threadId: string) => void;
  onRefresh?: () => void;
}

export const ConversationList: React.FC<ConversationListProps> = ({
  conversations,
  selectedThreadId,
  onSelectThread,
  onRefresh,
}) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filtered = conversations.filter((c) => {
    const text = `${c.threadId} ${c.ownerUserId} ${c.trace?.status || ''}`.toLowerCase();
    return text.includes(searchTerm.toLowerCase());
  });

  const getStatusLabel = (status?: string) => {
    switch (status) {
      case 'pending_approval':
        return { label: 'Necesita aprobación', isRed: true };
      case 'escalated':
        return { label: 'Escalado', isRed: true };
      case 'completed':
        return { label: 'Finalizado', isRed: false };
      case 'queued':
      case 'generating':
      case 'deciding':
      case 'normalizing':
      case 'retrieving':
        return { label: 'En proceso', isRed: false };
      case 'denied':
        return { label: 'Rechazado', isRed: false };
      default:
        return { label: status || 'En proceso', isRed: false };
    }
  };

  return (
    <div className="panel-card" style={{ height: '100%' }}>
      <div className="panel-header">
        <span>Conversaciones ({conversations.length})</span>
        {onRefresh && (
          <button
            onClick={onRefresh}
            className="btn-secondary"
            style={{ padding: '0.2rem 0.5rem', fontSize: '0.75rem' }}
            title="Refrescar lista"
            type="button"
          >
            🔄
          </button>
        )}
      </div>

      <div style={{ padding: '0.75rem', borderBottom: '1px solid var(--line-color)' }}>
        <input
          type="text"
          placeholder="Buscar por cliente o ID..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: '100%',
            padding: '0.45rem 0.75rem',
            border: '1px solid var(--line-color)',
            borderRadius: 'var(--control-radius)',
            fontSize: '0.85rem',
          }}
        />
      </div>

      <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column' }}>
        {filtered.length === 0 ? (
          <div style={{ padding: '1.5rem', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
            No se encontraron conversaciones.
          </div>
        ) : (
          filtered.map((item) => {
            const isSelected = item.threadId === selectedThreadId;
            const statusInfo = getStatusLabel(item.trace?.status);
            const lastMsg = item.messages?.[item.messages.length - 1];

            return (
              <div
                key={item.threadId}
                onClick={() => onSelectThread(item.threadId)}
                style={{
                  padding: '0.85rem 1rem',
                  borderBottom: '1px solid var(--line-color)',
                  cursor: 'pointer',
                  backgroundColor: isSelected ? 'var(--blue-soft)' : 'transparent',
                  borderLeft: isSelected ? '4px solid var(--blue-primary)' : '4px solid transparent',
                  transition: 'background-color 0.15s ease',
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.3rem' }}>
                  <span style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--text-ink)' }}>
                    {item.ownerUserId}
                  </span>
                  {statusInfo.isRed && (
                    <span
                      style={{
                        width: '8px',
                        height: '8px',
                        borderRadius: '50%',
                        backgroundColor: 'var(--red-primary)',
                        display: 'inline-block',
                      }}
                      title="Requiere atención inmediata"
                    />
                  )}
                </div>

                <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', marginBottom: '0.4rem' }}>
                  {lastMsg ? lastMsg.content : 'Sin mensajes'}
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.75rem' }}>
                  <span style={{ color: 'var(--text-muted)', fontStyle: 'italic' }}>
                    Estado: {statusInfo.label}
                  </span>
                  <span style={{ color: 'var(--text-muted)', fontSize: '0.7rem' }}>
                    Rev: #{item.revision}
                  </span>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};
